    {
      "name": "Limit",
      "aliases": [
        "Limit",
        "极限"
      ],
      "definition_snippet": "The value that a function approaches as the input approaches some value.",
      "category": "concept"
    },
    {
      "name": "Continuity",
      "aliases": [
        "Continuity",
        "连续性"
      ],
      "definition_snippet": "A function is continuous at a point if the limit equals the function value there.",
      "category": "concept"
    },
    {
      "name": "Derivative",
      "aliases": [
        "Derivative",
        "导数"
      ],
      "definition_snippet": "The instantaneous rate of change of a function at a given point.",
      "category": "concept"
    },
    {
      "name": "Instantaneous Rate of Change",
      "aliases": [
        "Instantaneous Rate of Change",
        "瞬时变化率"
      ],
      "definition_snippet": "The rate at which a quantity changes at a specific instant.",
      "category": "concept"
    },
    {
      "name": "Squeeze Theorem",
      "aliases": [
        "Squeeze Theorem",
        "夹逼定理"
      ],
      "definition_snippet": "If g(x) ≤ f(x) ≤ h(x) and lim g = lim h = L, then lim f = L.",
      "category": "theorem"
    },
    {
      "name": "Chain Rule",
      "aliases": [
        "Chain Rule",
        "链式法则"
      ],
      "definition_snippet": "Derivative of a composite function: [f(g(x))]' = f'(g(x)) · g'(x).",
      "category": "operation"
    },
    {
      "name": "Implicit Differentiation",
      "aliases": [
        "Implicit Differentiation",
        "隐函数求导"
      ],
      "definition_snippet": "Technique to find derivatives of equations not explicitly solved for y.",
      "category": "operation"
    },
    {
      "name": "Fundamental Theorem of Calculus",
      "aliases": [
        "Fundamental Theorem of Calculus",
        "微积分基本定理"
