      "category": "theorem"
    },
    {
      "name": "Riemann Sum",
      "aliases": [
        "Riemann Sum",
        "黎曼和"
      ],
      "definition_snippet": "Approximation of area under a curve using sums of rectangular areas.",
      "category": "concept"
    },
    {
      "name": "Definite Integral",
      "aliases": [
        "Definite Integral",
        "定积分"
      ],
      "definition_snippet": "Exact area under a curve over an interval, defined as the limit of Riemann sums.",
      "category": "concept"
    },
    {
      "name": "Mean Value Theorem",
      "aliases": [
        "Mean Value Theorem",
        "中值定理"
      ],
      "definition_snippet": "There exists c such that f'(c) = [f(b)-f(a)]/(b-a) on [a,b].",
      "category": "theorem"
    },
    {
      "name": "Extreme Value Theorem",
      "aliases": [
        "Extreme Value Theorem",
        "极值定理"
      ],
      "definition_snippet": "A continuous function on a closed interval attains absolute maximum and minimum.",
      "category": "theorem"
    },
    {
      "name": "L'Hospital's Rule",
      "aliases": [
        "L'Hospital's Rule",
        "洛必达法则"
      ],
